import time
import requests

def fetch_with_retry(url, tries=4, timeout=10):
    delay = 1.0
    for attempt in range(tries):
        try:
            r = requests.get(url, timeout=timeout)
            r.raise_for_status()
            return r.json()
        except (requests.RequestException, ValueError) as e:
            if attempt == tries - 1:
                raise
            time.sleep(delay)
            delay *= 2
